/* Dossier presentation only. Catalog calculations and character persistence stay in V2/app. */
window.ND_DOSSIER=(()=>{
 const states=new Map();let currentKey=null;
 const V=()=>window.ND_CATALOG_V2;
 const sign=n=>n<0?'−'+Math.abs(n):'+'+n;
 const symbols={
  overview:'M3 7h6l3 3h9v11H3Z M3 7V4h6l3 3h9v3',
  inventory:'M3 7h18v14H3Z M8 7V4h8v3 M3 12h18 M10 11v4h4v-4',
  chrome:'M6 6h12v12H6Z M9 2v4 M15 2v4 M9 18v4 M15 18v4 M2 9h4 M2 15h4 M18 9h4 M18 15h4',
  network:'M12 8v4 M6 17l4-5h4l4 5 M15 5a3 3 0 1 1-6 0 3 3 0 0 1 6 0 M8 19a3 3 0 1 1-6 0 3 3 0 0 1 6 0 M22 19a3 3 0 1 1-6 0 3 3 0 0 1 6 0',
  notes:'M12 5v16 M12 5C8 2 5 3 2 4v15c4-1 7-1 10 2 3-3 6-3 10-2V4c-3-1-6-2-10 1',
  'city-map':'m2 5 6-3 8 3 6-3v17l-6 3-8-3-6 3Z M8 2v17 M16 5v17',
  health:'M9 3h6v6h6v6h-6v6H9v-6H3V9h6Z',
  armor:'m12 2 9 4v6c0 5-5 8-9 10-4-2-9-5-9-10V6Z M12 7v9 M8 9v3c0 2 2 4 4 5 2-1 4-3 4-5V9',
  experience:'m4 10 8-7 8 7 M4 16l8-7 8 7 M4 22l8-7 8 7',
  attributes:'M3 14h4v8H3Z M10 8h4v14h-4Z M17 2h4v20h-4Z',
  skills:'M12 2v4 M12 18v4 M2 12h4 M18 12h4 M20 12a8 8 0 1 1-16 0 8 8 0 0 1 16 0 M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',
  weapons:'M3 5h18v5H9l-2 9H3l2-9H2V7h19 M11 10v4h5l2-4',
  perks:'m12 2 3 6 7 1-5 5 1 8-6-4-6 4 1-8-5-5 7-1Z',
  edit:'m4 16-1 5 5-1L21 7l-5-5Z M13 5l5 5 M4 16l4 4',
  photo:'M3 7h5l2-3h4l2 3h5v14H3Z M16 13a4 4 0 1 1-8 0 4 4 0 0 1 8 0',
  export:'M12 2v13 M7 10l5 5 5-5 M4 17v5h16v-5',
  import:'M12 17V3 M7 8l5-5 5 5 M4 17v5h16v-5',
  share:'M15 3h6v6 M21 3l-10 10 M10 5H3v16h16v-7',
  chevron:'m5 9 7 7 7-7',
  controls:'M4 5h16 M4 12h16 M4 19h16 M8 2v6 M16 9v6 M10 16v6',
  document:'M5 2h10l4 4v16H5Z M15 2v5h4 M8 11h8 M8 15h8 M8 19h5'
 };
 function uiIcon(name){return `<svg class="dossier-ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="${symbols[name]||symbols.document}"/></svg>`;}
 function state(){const key=cloudRecord?.id||'local';if(!states.has(key)){const mobile=window.matchMedia?.('(max-width: 899px)').matches??false;states.set(key,{open:{attributes:!mobile,skills:!mobile,weapons:!mobile,perks:!mobile,bio:false},filter:'mastered',editing:null,info:{}});}currentKey=key;return states.get(key);}
 function remember(){if(!currentKey||!states.has(currentKey))return;const s=states.get(currentKey);document.querySelectorAll('[data-dossier-open]').forEach(el=>s.open[el.dataset.dossierOpen]=el.open);document.querySelectorAll('[data-dossier-info]').forEach(el=>s.info[el.dataset.dossierInfo]=el.open);}
 function module(id,title,meta,body){return `<details class="dossier-module dossier-${id} ${id==='perks'?'dossier-surface-base':'dossier-surface-structural'}" data-dossier-open="${id}" ${state().open[id]?'open':''}><summary>${uiIcon(id)}<span>${title}</span><small>${esc(meta)}</small><b aria-hidden="true">${uiIcon('chevron')}</b></summary><div class="dossier-module-body">${body}</div></details>`;}
 function sources(stat){return stat.sources?.length?`<ul class="dossier-sources">${stat.sources.map(s=>`<li>${esc(s.name)} <b>${sign(s.value)}</b></li>`).join('')}</ul>`:'';}
 function stat(type,i){return window.ND_SHEET_V2.stat(type,i);}
 function values(type,i){const x=stat(type,i),editing=canManageStats()&&state().editing===type;if(type==='skills'&&!editing&&!x.permanentBonus)return `<div class="dossier-values dossier-skill-total"><strong class="dossier-effective" aria-label="Итого ${x.effective}">${x.effective}</strong></div>`;return `<div class="dossier-values"><span class="dossier-base" title="Базовое значение">${editing?selector(type+'.'+i,x.base,type==='attributes'?[0,1,2]:[0,1,2,3],(type==='attributes'?D.attributes:D.skills)[i].name):x.base}</span>${x.permanentBonus?`<span class="dossier-bonus" title="Постоянный бонус снаряжения">${sign(x.permanentBonus)}</span>`:'<span class="dossier-zero" aria-hidden="true">+0</span>'}<strong class="dossier-effective" aria-label="Итого ${x.effective}"><small>=</small> ${x.effective}</strong></div>`;}
 function editButton(type){const title=state().editing===type?'Завершить редактирование':type==='attributes'?'Редактировать характеристики':'Редактировать навыки';return canManageStats()?`<button type="button" class="dossier-edit-values" data-dossier-edit="${type}" aria-label="${title}" title="${title}" aria-pressed="${state().editing===type}">${uiIcon('edit')}</button>`:'';}
 function rootNetworkContext(type,i){return window.ND_NETWORK?.contextMarkup(card,D.catalog,type==='attributes'?'attribute':'skill',(type==='attributes'?V().attributeIds:V().skillIds)[i],D)||'';}
 function info(type,i,name,description){const id=type+'-'+i;return `<details class="dossier-info" data-dossier-info="${id}" ${state().info[id]?'open':''}><summary>${esc(name)}<span aria-hidden="true">ⓘ</span></summary><div><p>${esc(description)}</p>${sources(stat(type,i))}${rootNetworkContext(type,i)}</div></details>`;}
 function attributes(){return module('attributes','Характеристики','04',`${canManageStats()?`<div class="dossier-section-tools dossier-master-tools">${editButton('attributes')}</div>`:''}<div class="dossier-stat-table">${D.attributes.map((a,i)=>`<div class="dossier-stat-row"><span class="dossier-row-index">0${i+1}</span>${info('attributes',i,a.name,a.description)}${values('attributes',i)}</div>`).join('')}</div>`);}
 function skills(){const s=state(),rows=D.skills.map((x,i)=>({x,i,stat:stat('skills',i)})).filter(x=>s.filter==='all'||x.stat.base>0||x.stat.permanentBonus!==0||!!rootNetworkContext('skills',x.i));return module('skills','Навыки',String(D.skills.length),`<div class="dossier-section-tools"><div class="dossier-skill-filters" role="group" aria-label="Показать навыки"><button data-dossier-filter="mastered" aria-pressed="${s.filter==='mastered'}">Освоенные</button><button data-dossier-filter="all" aria-pressed="${s.filter==='all'}">Все</button></div>${editButton('skills')}</div><div class="dossier-skill-table">${rows.map(({x,i,stat:v})=>`<div class="dossier-skill-row">${info('skills',i,x.name,x.description)}<span class="dossier-rank" aria-label="Базовый ранг ${v.base} из 3">${[1,2,3].map(n=>`<i class="${n<=v.base?'filled':''}"></i>`).join('')}</span>${values('skills',i)}</div>`).join('')||'<p class="dossier-empty">Освоенных навыков пока нет</p>'}</div><p class="dossier-budget">Свободные очки: <b>${E.derive(card,D.catalog).skillPoints}</b></p>`);}
 function owned(){const normalized=V().normalizeCharacter(card,D.catalog);return normalized.equipmentItems.map(instance=>({instance,item:V().resolve(D.catalog,instance.catalogId)||instance.snapshot})).filter(x=>x.item&&x.instance.quantity>0);}
 function icon(item){return (typeof catalogIcon==='function'?catalogIcon(item,'dossier-item-icon'):'')||'<span class="dossier-icon-placeholder" aria-hidden="true"><svg viewBox="0 0 32 32" fill="none" stroke="currentColor"><path d="M5 9h22v14H5z M11 9V5h10v4 M5 15h22 M14 15v4h4v-4"/></svg></span>';}
 function rules(item){return `<details class="dossier-item-rules"><summary>Описание и особые правила</summary><p>${esc(item.description||'Описание не задано')}</p>${item.rulesText&&item.rulesText!==item.description?`<p>${esc(item.rulesText)}</p>`:''}</details>`;}
 function weapons(){const rows=owned().filter(({instance:x,item})=>x.location==='equipped'&&x.equipped!==false&&['ranged_weapon','melee_weapon'].includes(item.classId));return module('weapons','Активное оружие',String(rows.length),`${rows.map(({item})=>{const x=item.stats||{},range=item.classId==='melee_weapon'?(x.reach??item.range):(x.rangeMin!=null||x.rangeMax!=null?`${x.rangeMin??'?'}–${x.rangeMax??'?'}`:item.range);return `<article class="dossier-weapon-preview"><div class="dossier-item-heading">${icon(item)}<div><span class="dossier-item-status">Экипировано</span><h3>${esc(item.displayName||item.name)}</h3></div></div><dl class="dossier-weapon-stats"><div><dt>Урон</dt><dd>${esc(x.damage??item.damage??'—')}</dd></div><div><dt>${item.classId==='melee_weapon'?'Досягаемость':'Дальность'}</dt><dd>${esc(range??'—')}</dd></div><div><dt>Хват</dt><dd>${esc(x.hands!=null?x.hands===1?'1 рука':'2 руки':item.slot??'—')}</dd></div></dl>${rules(item)}</article>`;}).join('')||'<p class="dossier-empty">Оружие не экипировано</p>'}`);}
 function perks(){const rows=owned().filter(({instance:x,item})=>item.classId==='perk'&&(x.location==='learned'||x.metadata?.learned===true));return module('perks','Перки и способности',String(rows.length),`<div class="dossier-perk-list">${rows.map(({item})=>{const text=item.description||item.rulesText||'',activation=item.equipment?.activation;return `<article class="dossier-perk">${typeof catalogIcon==='function'?catalogIcon(item,'dossier-perk-icon'):''}<span class="dossier-item-status">${activation==='active'?'Активный':activation==='passive'?'Пассивный':'Тип не указан'}</span><h3>${esc(item.displayName||item.name)}</h3><p>${esc(text.length>170?text.slice(0,167)+'…':text)}</p>${rules(item)}</article>`;}).join('')||'<p class="dossier-empty">Изученных перков пока нет</p>'}</div>`);}
 function adjust(kind,value,max,automatic){return '<details class="dossier-resource-adjust"><summary aria-label="'+(kind==='hp'?'Максимум здоровья':'Максимум защиты')+'" title="Изменить максимум">'+uiIcon('controls')+'</summary><div class="dossier-resource-max-editor"><label>Максимальное значение<input type="number" data-resource-max="'+kind+'" aria-label="'+(kind==='hp'?'Максимум здоровья':'Максимум защиты')+'" min="0" max="10000" step="1" value="'+max+'"></label><small>По правилам: '+automatic+'</small><button type="button" data-resource-max-reset="'+kind+'">Сбросить к расчёту</button></div></details>';}

 function meter(kind,value,max){if(kind==='health'||kind==='armor'){const resource=kind==='health'?'hp':'armor',name=kind==='health'?'Здоровье':'Активная защита',count=Math.max(0,Math.trunc(max));return '<div class="dossier-health-segments dossier-resource-cells dossier-resource-'+kind+'" role="group" aria-label="'+name+': '+value+' из '+max+'" style="--resource-columns:'+Math.max(1,Math.min(8,count))+'">'+(Array.from({length:count},(_,i)=>{const filled=i<value,enabled=canEdit,target=filled?value-1:value+1,action=!canEdit?'Только просмотр':filled?(kind==='health'?'Получить 1 урон':'Потратить 1 ячейку защиты'):'Восстановить 1 ячейку';return '<button type="button" class="dossier-resource-cell '+(filled?'filled':'')+'" data-pip="'+resource+'" data-value="'+target+'" aria-label="'+name+', ячейка '+(i+1)+' из '+max+': '+action+'" title="'+action+'" aria-pressed="'+filled+'" '+(enabled?'':'disabled')+'><i aria-hidden="true"></i></button>';}).join('')||'<span class="dossier-no-resource" aria-hidden="true">—</span>')+'</div>';}const percent=max>0?Math.max(0,Math.min(100,value/max*100)):0;return '<div class="dossier-meter dossier-meter-'+kind+'" aria-hidden="true"><i style="width:'+percent+'%"></i></div>';}

 function armorSelector(active){const items=V().all(D.catalog).filter(x=>x.classId==='clothing_armor'&&(!x.archived||x.catalogId===active?.catalogId));return `<label class="dossier-armor-select"><span class="dossier-visually-hidden">Одежда и защита из справочника</span><select id="dossier-armor-choice" aria-label="Одежда и защита из справочника" ${!canEdit?'disabled':''}><option value="">Без брони</option>${items.map(x=>`<option value="${esc(x.catalogId)}" ${x.catalogId===active?.catalogId?'selected':''}>${esc(x.displayName||x.name)}</option>`).join('')}</select></label>`;}
 function metrics(){const d=E.derive(card,D.catalog),armor=owned().filter(({instance:x,item})=>x.location==='equipped'&&x.equipped!==false&&item.classId==='clothing_armor').sort((a,b)=>(b.item.stats?.armor||0)-(a.item.stats?.armor||0))[0]?.item;return `<div class="metrics dossier-metrics"><section class="dossier-metric dossier-health dossier-surface-technical"><h2>${uiIcon('health')}<span>Здоровье</span></h2><div class="dossier-metric-number">${card.hp}<small>/ ${d.maxHP}</small></div>${meter('health',card.hp,d.maxHP)}${canManageStats()?adjust('hp',card.hp,d.maxHP,d.stats.automaticMaxHP):''}</section><section class="dossier-metric dossier-armor dossier-surface-technical"><h2>${uiIcon('armor')}<span>Активная защита</span></h2><div class="dossier-metric-number">${d.currentArmor}<small>/ ${d.armor}</small></div>${meter('armor',d.currentArmor,d.armor)}${armorSelector(armor)}${canManageStats()?adjust('armor',d.currentArmor,d.armor,d.stats.automaticArmor):''}</section><section class="dossier-metric dossier-chrome dossier-surface-technical"><h2>${uiIcon('chrome')}<span>Хром</span></h2><div class="dossier-metric-number">${d.used}<small>/ ${d.capacity}</small></div>${meter('chrome',d.used,d.capacity)}<p class="${d.freeChrome<0?'warning':''}">${d.freeChrome>=0?'Свободно слотов: '+d.freeChrome:'Превышение лимита: '+(-d.freeChrome)}</p></section><section class="dossier-metric dossier-experience dossier-surface-technical"><h2>${uiIcon('experience')}<label for="experience-value">Опыт</label></h2><input id="experience-value" data-path="experience" type="number" min="0" step="1" inputmode="numeric" value="${card.experience??0}" aria-label="Очки опыта" ${!canEdit?'disabled':''}> <button id="spend-experience" ${!canEdit||!E.canSpendExperience(card)?'disabled':''}>Потратить ↗</button><span id="experience-hint" class="dossier-xp-hint">${E.canSpendExperience(card)?'Доступно развитие':'Нужно минимум 3 очка'}</span></section></div>`;}
 function identity(){return `<aside class="dossier-sidebar dossier-surface-base dossier-surface-grunge" aria-label="Личное дело"><div class="dossier-file-label"><h2>Личное дело</h2>${canEdit?`<button id="dossier-edit-identity" aria-label="Редактировать личное дело" title="Редактировать">${uiIcon('edit')}</button>`:''}</div><div class="dossier-person"><div class="dossier-portrait">${card.photo?`<img src="${esc(card.photo)}" alt="Портрет персонажа">`:'<svg class="dossier-silhouette" viewBox="0 0 100 120" aria-label="Портрет не добавлен" role="img"><circle cx="50" cy="35" r="22"/><path d="M10 115v-22c0-35 80-35 80 0v22Z"/></svg>'}${canEdit?`<button id="edit-photo" aria-label="Изменить фото персонажа" title="Изменить фото">${uiIcon('photo')}</button>`:''}</div><div class="dossier-identity"><h2 class="dossier-nickname">${esc(card.nickname||'Без псевдонима')}</h2><p class="dossier-real-name">${esc(card.name||'Имя не указано')}</p><div class="dossier-age"><span>Возраст</span><b>${esc(card.age||'Не указан')}</b></div></div></div><details class="dossier-bio" data-dossier-open="bio" ${state().open.bio?'open':''}><summary>${uiIcon('document')}<span>Краткая история</span>${uiIcon('chevron')}</summary><p>${esc(card.bio||'История ещё не написана')}</p>${canEdit?'<button id="dossier-edit-bio">Изменить историю</button>':''}</details></aside>`;}
 function render(){state();return `<div class="dossier-layout">${identity()}<div class="dossier-main">${metrics()}<div class="dossier-details-grid">${attributes()}${skills()}</div><div class="dossier-loadout-grid">${weapons()}${perks()}</div></div></div>`;}
 function editIdentity(bio=false){if(!canEdit)return;modal(bio?'Краткая история':'Идентификация',`<form id="dossier-identity-form">${bio?`<label class="field">История<textarea name="bio" rows="7" maxlength="20000">${esc(card.bio)}</textarea></label>`:`<label class="field">Никнейм<input name="nickname" maxlength="20000" value="${esc(card.nickname)}"></label><label class="field">Имя персонажа<input name="name" maxlength="20000" value="${esc(card.name)}"></label><label class="field">Возраст<input name="age" maxlength="20000" value="${esc(card.age)}"></label>`}<button class="yellow" type="submit">Сохранить</button></form>`);$('#dossier-identity-form').onsubmit=e=>{e.preventDefault();if(!canEdit)return;try{const fields=bio?['bio']:['nickname','name','age'],next=E.clone(card);fields.forEach(k=>next[k]=e.currentTarget.elements[k].value);E.validate(next,D);fields.forEach(k=>card[k]=next[k]);changed();closeModal();window.ND_DOSSIER.remember();window.ND_DOSSIER.refresh();}catch(err){error(err);}};}
 function bind(){document.querySelectorAll('[data-resource-max]').forEach(el=>{el.onchange=()=>{if(!canManageStats())return;try{if(el.value==='')throw Error('Укажи максимальное значение');setResourceMaximum(el.dataset.resourceMax,Number(el.value));}catch(err){notify(err.message);refresh();}};el.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();el.blur();}};});document.querySelectorAll('[data-resource-max-reset]').forEach(b=>b.onclick=()=>{if(canManageStats())setResourceMaximum(b.dataset.resourceMaxReset,null);});if($('#dossier-armor-choice'))$('#dossier-armor-choice').onchange=e=>{if(!canEdit)return;try{window.ND_SHEET_V2.equipArmor(e.target.value);}catch(err){notify(err.message);refresh();}};const boundState=state();document.querySelectorAll('[data-dossier-open]').forEach(el=>el.ontoggle=()=>{boundState.open[el.dataset.dossierOpen]=el.open;});document.querySelectorAll('[data-dossier-info]').forEach(el=>el.ontoggle=()=>{boundState.info[el.dataset.dossierInfo]=el.open;});document.querySelectorAll('[data-dossier-filter]').forEach(b=>b.onclick=()=>{remember();state().filter=b.dataset.dossierFilter;refresh();});document.querySelectorAll('[data-dossier-edit]').forEach(b=>b.onclick=()=>{if(!canManageStats())return;remember();const s=state();s.editing=s.editing===b.dataset.dossierEdit?null:b.dataset.dossierEdit;if(s.editing==='skills')s.filter='all';refresh();});if($('#dossier-edit-identity'))$('#dossier-edit-identity').onclick=()=>editIdentity();if($('#dossier-edit-bio'))$('#dossier-edit-bio').onclick=()=>editIdentity(true);}
 // Alias avoids shadowing the application render function inside this module.
 function refresh(){renderCharacterSheet();}
 return {render,remember,bind,refresh,uiIcon};
})();
